CREATE TABLE IF NOT EXISTS ai_eval_dataset (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,description VARCHAR(500),enabled TINYINT NOT NULL DEFAULT 1,created_at DATETIME,updated_at DATETIME);
CREATE TABLE IF NOT EXISTS ai_eval_case (id BIGINT PRIMARY KEY AUTO_INCREMENT,dataset_id BIGINT NOT NULL,question TEXT NOT NULL,expected_answer TEXT,expected_doc_ids VARCHAR(1000),required_keywords VARCHAR(2000),forbidden_claims VARCHAR(2000),no_answer TINYINT NOT NULL DEFAULT 0,tags VARCHAR(500),remark VARCHAR(1000),enabled TINYINT NOT NULL DEFAULT 1,created_at DATETIME,updated_at DATETIME,INDEX idx_eval_case_dataset(dataset_id));
CREATE TABLE IF NOT EXISTS ai_eval_run (id BIGINT PRIMARY KEY AUTO_INCREMENT,dataset_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL,total_cases INT NOT NULL DEFAULT 0,completed_cases INT NOT NULL DEFAULT 0,passed_cases INT NOT NULL DEFAULT 0,recall_at_k DOUBLE,mrr DOUBLE,citation_validity DOUBLE,citation_coverage DOUBLE,refusal_rate DOUBLE,p95_latency_ms BIGINT,total_tokens BIGINT,error_msg VARCHAR(1000),started_at DATETIME,finished_at DATETIME,created_at DATETIME,INDEX idx_eval_run_dataset(dataset_id));
CREATE TABLE IF NOT EXISTS ai_eval_result (id BIGINT PRIMARY KEY AUTO_INCREMENT,run_id BIGINT NOT NULL,case_id BIGINT NOT NULL,status VARCHAR(20),question TEXT,answer TEXT,sources_json LONGTEXT,matched_doc_ids VARCHAR(1000),recall_hit TINYINT,reciprocal_rank DOUBLE,citation_valid TINYINT,citation_coverage TINYINT,refusal_correct TINYINT,latency_ms BIGINT,total_tokens INT,error_msg VARCHAR(1000),created_at DATETIME,INDEX idx_eval_result_run(run_id));
CREATE TABLE IF NOT EXISTS ai_answer_feedback (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,message_id BIGINT NOT NULL,session_id BIGINT,vote VARCHAR(8) NOT NULL,reason VARCHAR(80),created_at DATETIME,updated_at DATETIME,UNIQUE KEY uk_feedback_user_message(user_id,message_id),INDEX idx_feedback_message(message_id));
